def lines(x,y,values):return ''.join(text(x,y+22*i,v,18) for i,v in enumerate(values))
def pump(x,y,color):
    s=f'<circle cx="{x}" cy="{y}" r="22" fill="{color}" stroke="#172033" stroke-width="2"/>'
    for a in range(0,360,60):s+=f'<path transform="rotate({a} {x} {y})" d="M{x} {y}q15 -20 18 -5q-10 0 -18 5" fill="#e0f2fe" stroke="#172033"/>'
    return s
