    b+='<g fill="none" stroke="#334155" stroke-width="1.5"><path d="M169 160H328M168 213H248M168 263H296M168 331H318M168 407H332M746 67H677L643 87M724 272H680M774 373Q724 373 724 412M700 516H648M594 597L568 545"/></g>'
